import {options,prepare} from './engine.mjs';
const $=id=>document.getElementById(id);let pockets=37,bets=[{type:'red',value:'',units:1}],worker;
const types={red:'Red · 1:1',black:'Black · 1:1',odd:'Odd · 1:1',even:'Even · 1:1',low:'1–18 · 1:1',high:'19–36 · 1:1',dozen:'Dozen · 2:1',column:'Column · 2:1',straight:'Single number · 35:1',split:'Split · 17:1',street:'Street · 11:1',corner:'Corner · 8:1',six:'Six-line · 5:1',basket:'0, 00, 1, 2, 3 · 6:1'};
const help={flat:'Same stake every spin. A useful baseline for any experiment.',martingale:'Double after a net loss; reset after a net win. Stakes can grow very quickly.',reverse:'Double after a net win; reset after a loss or the selected win streak.',fibonacci:'After losses: 1, 1, 2, 3, 5… units. After a win, move back two steps.',dalembert:'Add one unit after a net loss; subtract one after a win, never below one.'};
const fmt=n=>new Intl.NumberFormat('en',{maximumFractionDigits:2}).format(n),money=n=>(n<-.005?'−':n>.005?'+':'')+'¤'+fmt(Math.abs(n)),pct=n=>(n*100).toFixed(1)+'%';
function renderBets(){const root=$('bets');root.replaceChildren();bets.forEach((b,i)=>{const row=document.createElement('div');row.className='bet';const wrap=document.createElement('div');const label=document.createElement('label');label.htmlFor='bet'+i;label.textContent='Bet '+(i+1);const select=document.createElement('select');select.id='bet'+i;for(const [k,v] of Object.entries(types)){if(k==='basket'&&pockets!==38)continue;select.add(new Option(v,k));}select.value=b.type;select.onchange=()=>{b.type=select.value;b.value=options(b.type,pockets)[0]?.value||'';renderBets();dirty();};wrap.append(label,select);const unitsWrap=document.createElement('div');const ul=document.createElement('label');ul.textContent='Units';ul.htmlFor='units'+i;const units=document.createElement('input');units.id='units'+i;units.type='number';units.min='1';units.max='100';units.step='1';units.value=b.units;units.oninput=()=>{b.units=Number(units.value);dirty();};unitsWrap.append(ul,units);const rem=document.createElement('button');rem.textContent='×';rem.className='remove';rem.setAttribute('aria-label','Remove bet '+(i+1));rem.disabled=bets.length===1;rem.onclick=()=>{bets.splice(i,1);renderBets();dirty();};row.append(wrap,unitsWrap,rem);const opts=options(b.type,pockets);if(opts.length){if(!opts.some(o=>o.value===b.value))b.value=opts[0].value;const detail=document.createElement('select');detail.className='bet-detail';detail.setAttribute('aria-label','Numbers for bet '+(i+1));for(const o of opts)detail.add(new Option(o.label,o.value));detail.value=b.value;detail.onchange=()=>{b.value=detail.value;dirty();};row.append(detail);}root.append(row);});$('addBet').disabled=bets.length>=8;}
function dirty(){if(!$('output').hidden)$('status').textContent='Settings changed · run again';}
$('addBet').onclick=()=>{if(bets.length<8){bets.push({type:'black',value:'',units:1});renderBets();dirty();}};
document.querySelectorAll('[data-wheel]').forEach(b=>b.onclick=()=>{pockets=+b.dataset.wheel;document.querySelectorAll('[data-wheel]').forEach(x=>x.classList.toggle('active',x===b));bets.forEach(x=>{if(x.type==='basket'&&pockets!==38){x.type='red';x.value='';}});$('edge').textContent=`${pockets} pockets · ${((pockets-36)/pockets*100).toFixed(2)}% standard house edge`;$('emptyEdge').textContent=((pockets-36)/pockets*100).toFixed(2)+'%';renderBets();dirty();});
$('strategy').onchange=()=>{$('strategyHelp').textContent=help[$('strategy').value]+' Break-even spins leave the progression unchanged.';dirty();};$('strategy').onchange();renderBets();document.querySelectorAll('.controls input,.controls select').forEach(e=>e.addEventListener('input',dirty));
function config(){const c={pockets,strategy:$('strategy').value,limitRule:$('limitRule').value,seed:$('seed').value,bets:structuredClone(bets)};for(const id of ['bankroll','base','spins','sessions','tableMax','takeProfit','stopLoss','resetWins']){const e=$(id);if(!e.checkValidity()||!e.value.trim())throw Error('Check '+e.labels?.[0]?.textContent+'.');c[id]=Number(e.value);}if(c.spins*c.sessions>10000000)throw Error('Choose at most 10 million total spins (spins × sessions).');if(!c.seed.trim())throw Error('Enter a seed so the experiment can be repeated.');const keys=new Set();for(const b of c.bets){if(!Number.isInteger(b.units)||b.units<1||b.units>100)throw Error('Bet units must be whole numbers from 1 to 100.');const key=b.type+':'+b.value;if(keys.has(key))throw Error('Combine duplicate bets into one row using more units.');keys.add(key);if(b.units*c.base>c.tableMax)throw Error('The base stake on a bet exceeds the table maximum.');}if(c.bets.reduce((s,b)=>s+c.base*b.units,0)>c.bankroll)throw Error('Your bankroll must cover the first combined stake.');return c;}
$('cancel').onclick=()=>{worker?.terminate();worker=null;$('run').disabled=false;$('cancel').hidden=true;$('status').textContent='Run canceled';};
$('run').onclick=()=>{let c;try{c=config();$('error').textContent='';}catch(e){$('error').textContent=e.message;return;}$('run').disabled=true;$('cancel').hidden=false;$('status').textContent='Simulating…';worker=new Worker('./worker.mjs',{type:'module'});worker.onmessage=e=>{if(e.data.progress!==undefined){$('status').textContent=`Simulating · ${Math.round(e.data.progress*100)}%`;return;}worker.terminate();worker=null;$('run').disabled=false;$('cancel').hidden=true;if(e.data.error){$('error').textContent=e.data.error;return;}show(e.data.results,c);};worker.onerror=()=>{$('error').textContent='The simulation could not run. Please reload and try again.';$('run').disabled=false;$('cancel').hidden=true;worker?.terminate();};worker.postMessage(c);};
function show(r,c){$('empty').hidden=true;$('output').hidden=false;$('status').textContent=`${fmt(r.length)} sessions complete`;$('resultTitle').textContent=`${$('strategy').options[Array.from($('strategy').options).findIndex(x=>x.value===c.strategy)].text} · ${c.pockets} pockets`;
const n=r.length,sum=k=>r.reduce((a,b)=>a+b[k],0),mean=sum('profit')/n,wins=r.filter(x=>x.profit>1e-7).length,ties=r.filter(x=>Math.abs(x.profit)<=1e-7).length,ruins=r.filter(x=>['bankrupt','cannot fund next bet'].includes(x.reason)).length,zero=r.filter(x=>x.bank<1e-7).length,variance=n>1?r.reduce((s,x)=>s+(x.profit-mean)**2,0)/(n-1):0,se=Math.sqrt(variance/n);$('mean').textContent=money(mean);$('meanNote').textContent=n>1?`Monte Carlo standard error: ¤${fmt(se)}`:'One session cannot estimate sampling error.';$('win').textContent=pct(wins/n);$('winNote').textContent=`${fmt(wins)} ahead · ${fmt(ties)} break-even`;$('ruin').textContent=pct(ruins/n);$('ruinNote').textContent=`${fmt(ruins)} stopped · ${fmt(zero)} finished at zero`;
const sorted=r.map(x=>x.profit).sort((a,b)=>a-b),q=p=>{const t=(n-1)*p,i=Math.floor(t);return sorted[i]+(sorted[Math.ceil(t)]-sorted[i])*(t-i);};$('p10').textContent=money(q(.1));$('median').textContent=money(q(.5));$('p90').textContent=money(q(.9));
const rows=[['Starting bankroll, each session','¤'+fmt(c.bankroll)],['Total amount wagered, all sessions','¤'+fmt(sum('wagered'))],['Total profit / loss, all sessions',money(sum('profit'))],['Average amount wagered','¤'+fmt(sum('wagered')/n)],['Average house-edge cost benchmark',money(sum('benchmark')/n)],['Actual spins played',fmt(sum('spins'))+' / '+fmt(c.spins*c.sessions)],['Average spins per session',fmt(sum('spins')/n)],['Random seed',c.seed]];const dl=$('audit');dl.replaceChildren();for(const [k,v]of rows){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;dd.style.overflowWrap='anywhere';dl.append(dt,dd);}$('benchmarkNote').textContent='The benchmark sums −stake × house edge for every wager. With adaptive stakes it is a cost benchmark, not a prediction conditional on this run’s turnover. Across many experiments, mean profit and mean benchmark converge in expectation. Sampling error is the standard deviation of session profits divided by √sessions; rare losses may still be undersampled.';const reasons={};for(const x of r)reasons[x.reason]=(reasons[x.reason]||0)+1;$('reasons').replaceChildren();for(const [k,v]of Object.entries(reasons)){const div=document.createElement('div');div.className='reason';const b=document.createElement('b');b.textContent=pct(v/n);div.append(b,document.createTextNode(k));$('reasons').append(div);}$('limitNote').textContent=`${fmt(r.filter(x=>x.limitHits).length)} sessions hit a table limit. Policy: ${c.limitRule==='stop'?'end the session':c.limitRule==='reset'?'reset the progression to its base':'cap all stakes proportionally and continue the progression'}. Every repeated session starts fresh. Results shown use the settings at the time of the run.`;drawPaths(r.slice(0,12),c);drawHistogram(sorted);if(innerWidth<741)document.querySelector('.results').scrollIntoView({behavior:'smooth',block:'start'});}
const NS='http://www.w3.org/2000/svg';function svgEl(root,tag,attrs,text){const el=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))el.setAttribute(k,v);if(text!==undefined)el.textContent=text;root.append(el);return el;}
const short=n=>Math.abs(n)>=1000000?(n/1000000).toFixed(1)+'m':Math.abs(n)>=10000?(n/1000).toFixed(0)+'k':fmt(n);
function drawPaths(r,c){const root=$('paths');root.replaceChildren();const all=r.flatMap(x=>x.path.map(p=>p.y));let lo=Math.min(0,...all),hi=Math.max(0,...all);if(lo===hi){lo=-1;hi=1;}const pad=(hi-lo)*.08;lo-=pad;hi+=pad;const x=s=>64+s/c.spins*670,y=v=>225-(v-lo)/(hi-lo)*210;for(let i=0;i<=4;i++){const v=lo+(hi-lo)*i/4;svgEl(root,'line',{x1:64,x2:734,y1:y(v),y2:y(v),stroke:'#e9ede5'});svgEl(root,'text',{x:54,y:y(v)+3,'text-anchor':'end'},short(v));}svgEl(root,'line',{x1:64,x2:734,y1:y(0),y2:y(0),stroke:'#8d9b86','stroke-dasharray':'4 5'});r.forEach((s,i)=>svgEl(root,'polyline',{points:s.path.map(p=>x(p.x)+','+y(p.y)).join(' '),fill:'none',stroke:['#49775e','#ba7656','#92a879','#92a5a0','#c5a260','#385a48'][i%6],'stroke-width':i===0?2:1.2,opacity:i===0?1:.65}));for(const t of [0,.25,.5,.75,1])svgEl(root,'text',{x:x(c.spins*t),y:247,'text-anchor':'middle'},short(c.spins*t));svgEl(root,'text',{x:400,y:268,'text-anchor':'middle'},'Spins played');}
function drawHistogram(sorted){const root=$('hist');root.replaceChildren();let lo=sorted[0],hi=sorted.at(-1);if(lo===hi){lo-=1;hi+=1;}const count=24,bins=Array(count).fill(0),width=(hi-lo)/count;for(const v of sorted)bins[Math.min(count-1,Math.floor((v-lo)/width))]++;const max=Math.max(...bins),x=i=>64+i/count*670;for(let i=0;i<=3;i++){const n=max*i/3,y=165-n/max*145;svgEl(root,'line',{x1:64,x2:734,y1:y,y2:y,stroke:'#edf0e9'});svgEl(root,'text',{x:54,y:y+3,'text-anchor':'end'},fmt(Math.round(n)));}bins.forEach((n,i)=>{const rect=svgEl(root,'rect',{x:x(i)+1,y:165-n/max*145,width:670/count-2,height:n/max*145,rx:2,fill:lo+(i+.5)*width<0?'#c17e61':'#6a9271'});svgEl(rect,'title',{},`${money(lo+i*width)} to ${money(lo+(i+1)*width)}: ${n} sessions`);});for(const t of [0,.25,.5,.75,1])svgEl(root,'text',{x:64+t*670,y:185,'text-anchor':'middle'},short(lo+t*(hi-lo)));svgEl(root,'text',{x:400,y:207,'text-anchor':'middle'},'Final session profit · bar height = session count');}
